// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Antik ve Doğu edebiyatları: Homeros, Şehname, Hint ve Çin klasikleri (kolay).
const ozLiterature12Kolay = <(String, String, List<String>, String)>[
  ('İlyada\'nın ilk dizesinde ozanın Mousa\'dan söylemesini istediği temel konu hangisidir?', 'Akhilleus\'un öfkesi', ['Truva atının yapılışı', 'Helene\'nin kaçırılışı', 'Odysseus\'un dönüş yolculuğu'], 'Eser \'Öfkeyi söyle, tanrıça\' diye başlar; konusu Akhilleus\'un öfkesi ve sonuçlarıdır, savaşın tamamı değil.'),
  ('İlyada\'da Akhilleus\'un ordudan çekilip savaşmayı bırakmasına yol açan olay hangisidir?', 'Agamemnon\'un onun ganimet kızı Briseis\'i elinden alması', ['Hektor\'un Akha gemilerini yakması', 'Patroklos\'un ölümü', 'Paris\'in Menelaos\'u dövüşte yenip Helene\'yi Truva\'ya götürmesi'], 'Agamemnon, Khryseis\'i babasına geri vermek zorunda kalınca onun yerine Akhilleus\'un payı olan Briseis\'i aldı; Akhilleus onurunun zedelendiğini düşünüp savaştan çekildi.'),
  ('İlyada\'da Akhilleus yeniden savaşa girmek için hangi olay yüzünden Agamemnon\'la barışır?', 'Patroklos\'un Hektor tarafından öldürülmesi', ['Briseis\'in Truva\'ya kaçması', 'Thetis\'in tanrılar katında yalvarması ve Zeus\'un araya girmesi', 'Ajax\'ın yaralanması'], 'Dostunun ölümü Akhilleus\'un öfkesini Agamemnon\'dan Hektor\'a çevirir ve onu savaşa döndürür.'),
  ('Akhilleus için yeni zırhı ve ayrıntılı bir kalkanı hangi tanrı yapmıştır?', 'Hephaistos', ['Ares', 'Apollon', 'Hermes'], 'Annesi Thetis\'in isteğiyle demirci tanrı Hephaistos zırhı ve üzerinde dünya sahnelerinin işlendiği kalkanı yapar.'),
  ('İlyada, aşağıdaki olaylardan hangisiyle sona erer?', 'Hektor\'un cenaze töreniyle', ['Truva\'nın tahta atla düşmesiyle', 'Akhilleus\'un ölümüyle', 'Agamemnon\'un Mykene\'ye dönüşüyle'], 'Eser Priamos\'un oğlunun cesedini geri almasıyla ve Hektor\'un gömülmesiyle biter; Truva\'nın yıkılışı anlatılmaz.'),
  ('İlyada\'da Priamos, oğlunun cesedini istemek için gece gizlice kime gider?', 'Akhilleus\'a', ['Agamemnon\'a', 'Odysseus\'a', 'Nestor\'a'], 'Hermes\'in yol göstermesiyle Akha kampına giren yaşlı kral, Akhilleus\'un ellerine kapanıp Hektor\'un cesedini ister.'),
  ('Hektor\'un oğlu Astyanaks\'ın annesi kimdir?', 'Andromakhe', ['Hekabe', 'Kassandra', 'Polyxena'], 'Andromakhe Hektor\'un eşi, Astyanaks da çocuklarıdır; Truva kadınları anlatılarında trajik bir figürdür.'),
  ('İlyada\'nın ikinci bölümünde Akha komutanlarının ve gemilerinin sayıldığı uzun listeye ne ad verilir?', 'Gemiler Katalogu', ['Kahramanlar Atlası', 'Truva Fihristi', 'Ordu Defteri'], 'Gemiler Katalogu, Yunan birliklerinin kökenlerini ve lider adlarını sıralar ve destanın tarihsel çerçevesini genişletir.'),
  ('İlyada\'da Akha ordusunun yaşlı ve bilge öğüt verici komutanı olarak bilinen, Pylos kralı kimdir?', 'Nestor', ['Idomeneus', 'Phoinix', 'Menelaos'], 'Nestor uzun konuşmaları ve deneyimiyle tanınır; hem İlyada\'da hem Odysseia\'da öğüt veren bilge olarak görünür.'),
  ('Akhilleus\'un savaşçı birliğine ne ad verilir?', 'Myrmidonlar', ['Dolopler', 'Lapithlar', 'Ainianlar'], 'Myrmidonlar, Akhilleus\'un Phthia\'dan getirdiği birliktir; Patroklos da onları savaşa sürer.'),
  ('Paris ile Menelaos arasındaki tekil dövüşte Menelaos üstün gelirken Paris\'i hangi tanrıça kurtarır?', 'Aphrodite', ['Athena', 'Hera', 'Artemis'], 'Aphrodite Paris\'i bir sis içinde alıp yatak odasına götürür; ardından Pandaros\'un ok atmasıyla ateşkes bozulur.'),
  ('Hektor\'u öldürdükten sonra Akhilleus\'un cesede yaptığı hangisidir?', 'Arabasının arkasına bağlayıp Truva surlarının önünde sürüklemesi', ['Cesedi Skamandros ırmağına atması', 'Cesedi Akha ordusuna teslim etmesi', 'Cesede onurlu bir tören yaptırması'], 'Bu davranış tanrıları da rahatsız eder; Zeus, Thetis aracılığıyla cesedin geri verilmesini sağlar.'),
  ('İlyada\'da Akhilleus ile uzlaşmak üzere Agamemnon tarafından gönderilen elçilik heyetinde aşağıdakilerden hangisi yer almaz?', 'Hektor', ['Odysseus', 'Aias', 'Phoinix'], 'Dokuzuncu bölümdeki elçilikte Odysseus, Aias ve Phoinix Akhilleus\'u ikna etmeye çalışır; Hektor ise Truva tarafındadır.'),
  ('Akhaları destekleyen tanrılar arasında hangisi sayılabilir?', 'Hera', ['Apollon', 'Ares', 'Aphrodite'], 'Hera ve Athena Akhaların yanındadır; Apollon, Ares ve Aphrodite ise genel olarak Truvalıları destekler.'),
  ('Patroklos\'un cenazesi için düzenlenen ve araba yarışı, güreş gibi dalları içeren etkinliğe ne ad verilir?', 'Cenaze oyunları', ['Panathenaia', 'Dionysia', 'Olimpiyat şenliği'], 'İlyada\'nın yirmi üçüncü bölümünde Patroklos için cenaze oyunları düzenlenir; bu gelenek Yunan atletizm şenliklerinin kökeni sayılır.'),
  ('Odysseus\'un gözünü kör ettiği Kyklops Polyphemos hangi tanrının oğludur?', 'Poseidon', ['Zeus', 'Hades', 'Apollon'], 'Polyphemos Poseidon\'un oğludur; bu yüzden deniz tanrısı Odysseus\'un dönüşünü uzun yıllar zorlaştırır.'),
  ('Odysseus\'un adamlarını domuza çeviren büyücü kadın ve onun büyüsünden kurtaran bitki hangi seçenekte doğru verilmiştir?', 'Kirke ile moly', ['Kalypso ile lotos', 'Kirke ile ambrosia', 'Nausikaa ile moly'], 'Hermes, Odysseus\'a moly adlı bitkiyi verir; bu bitki Kirke\'nin büyüsünü etkisiz kılar.'),
  ('Odysseus, Sirenlerin şarkısını dinlemek için hangi önlemi alır?', 'Kendini direğe bağlatır, tayfaların kulaklarını balmumuyla tıkar', ['Tayfaları uyutur, kendi gözlerini bağlar', 'Gemiyi bir adaya demirler', 'Tayfalarla birlikte şarkıya karşı şarkı söyler ve gemiyi hızlandırır'], 'Kirke\'nin öğüdüne uyan Odysseus şarkıyı duyar ama kendini kurtarır; adamları ise balmumu sayesinde duymaz.'),
  ('Odysseus\'un gemisinin geçmek zorunda kaldığı dar boğazda tehlikeyi oluşturan canavar ve girdap çifti hangisidir?', 'Skylla ve Kharybdis', ['Kerberos ve Hydra', 'Gorgon ve Minotauros', 'Sphinks ve Khimaira'], 'Odysseus Skylla\'nın altı adamını yitirmeyi göze alarak Kharybdis\'in girdabından kaçınır.'),
  ('Odysseus\'u Ogygia adasında yıllarca alıkoyan, ona ölümsüzlük vaat eden periye ne ad verilir?', 'Kalypso', ['Kirke', 'Nausikaa', 'Leukothea'], 'Kalypso Odysseus\'u sevgilisi yapmak istemiş, ancak Zeus\'un buyruğuyla Hermes gelince onu bırakmıştır.'),
  ('Odysseus, kıyıya vurduktan sonra kendisine çamaşır yıkarken yardım eden genç kız kimdir?', 'Nausikaa', ['Penelope', 'Eurykleia', 'Kirke'], 'Phaiak kralı Alkinoos\'un kızı Nausikaa, Odysseus\'u saraya götürür ve konukseverlikle karşılanmasını sağlar.'),
  ('Odysseia\'da Penelope, talipleri oyalamak için hangi hileyi kullanır?', 'Laertes için dokuduğu kefeni geceleri sökerek', ['Her gün başka bir talibe söz verip bütün talipleri oyalayarak', 'Bir yay yarışması düzenleyerek', 'Tanrılardan kehanet isteyerek'], 'Kefen bitince bir talibini seçeceğini söyleyen Penelope gündüz dokur, geceleri söker; hile bir hizmetçinin ihbarıyla anlaşılır.'),
  ('Odysseus, yirmi yıl sonra İthaka\'ya döndüğünde kimliğini ilk olarak kime açıklar?', 'Oğlu Telemakhos\'a', ['Penelope\'ye', 'Taliplere', 'Eurykleia\'ya'], 'Domuz çobanı Eumaios\'un kulübesinde Telemakhos\'la buluşan Odysseus, Athena\'nın etkisiyle eski haline döner ve oğluna kimliğini açıklar.'),
  ('İthaka\'ya yıllar sonra dönen Odysseus\'u tanıyan ilk canlı hangisidir?', 'Köpeği Argos', ['Dadısı Eurykleia', 'Eumaios', 'Telemakhos'], 'Argos Odysseus\'u görünce kuyruğunu sallar ve ölür; dadısı Eurykleia ise onu sonradan yara izinden tanır.'),
  ('Eurykleia, Odysseus\'un ayağını yıkarken onu neden tanır?', 'Gençliğinde yaban domuzunun açtığı yara izini görür', ['Sesini hatırlar', 'Yüzüğünü fark eder', 'Kılıcını tanır'], 'Yara izi, Odysseus\'un gençlik yıllarından kalan bir avdan gelir ve kimliğin bedensel kanıtıdır.'),
  ('Odysseus, ölüler diyarında kendisine eve dönüşüyle ilgili öngörülerde bulunan kör kâhin kimdir?', 'Teiresias', ['Kalkhas', 'Amphiaraos', 'Helenos'], 'Hades\'e inen Odysseus, kurbanlık kanını sunarak Teiresias\'ın ruhunu konuşturur; kâhin dönüşünde karşılaşacağı tehlikeleri bildirir.'),
  ('Odysseia\'da Telemakhos\'un babasını aramak için gittiği iki yer hangi seçenekte doğru verilmiştir?', 'Pylos ve Sparta', ['Mykene ve Troya', 'Delphoi ve Atina', 'Knossos ve Thebai'], 'Telemakhos, Pylos\'ta Nestor\'u, Sparta\'da Menelaos ile Helene\'yi ziyaret ederek babası hakkında haber arar.'),
  ('Odysseus\'un adamlarının bir kısmının dönmeyi unutacak kadar tatlı bir meyveye kapılmasına konu olan topluluk hangisidir?', 'Lotos yiyenler', ['Laistrygonlar', 'Kimmerler', 'Phaiaklar'], 'Lotos meyvesini yiyen tayfalar yurtlarını unutur; Odysseus onları zorla gemiye getirir.'),
  ('Odysseia\'da Athena, Odysseus\'un oğluna yol göstermek için hangi kılığa girer?', 'Mentor', ['Nestor', 'Eumaios', 'Alkinoos'], 'Mentor adı sonradan \'deneyimli yol gösterici\' anlamında genel kavram haline gelmiştir.'),
  ('Aşağıdaki karakterlerden hangisi İthaka\'da Penelope\'nin talipleri arasında yer alır?', 'Antinoos', ['Eumaios', 'Laertes', 'Mentor'], 'Antinoos ve Eurymakhos taliplerin önde gelenleridir; Eumaios sadık çoban, Laertes Odysseus\'un babasıdır.'),
  ('Homeros destanlarının yazıldığı ölçü olan hekzametre, kaç ayaklı bir dize yapısıdır?', 'Altı ayaklı', ['Dört ayaklı', 'Beş ayaklı', 'Sekiz ayaklı'], 'Hekzametre sözcüğü \'altı ölçü\' demektir; dizeler altı ayaktan oluşur ve genellikle daktil ayağına dayanır.'),
  ('Homeros\'ta \'ayağı çabuk\', \'pembe parmaklı\', \'şarap renkli deniz\' gibi sabit sıfatlara ne ad verilir?', 'Epitet', ['Hiperbol', 'Paradoks', 'Alegori'], 'Epitetler hem hekzametre kalıbına uyum sağlar hem de sözlü anlatıcının hafızasını destekler.'),
  ('Antik Yunan\'da şenliklerde Homeros\'u okuyan, destan söyleyen kişilere ne denir?', 'Rhapsodos', ['Aoidos olmayan gezgin', 'Khoregos', 'Hypokrites'], 'Rhapsodos, \'dizeleri birbirine diken\' anlamına gelir; Homeros\'u ezberden okuyup yorumlayan seslendirici demektir.'),
  ('Homeros destanlarındaki uzun, ayrıntılı ve ana konudan sapar gibi görünen karşılaştırmalara ne denir?', 'Epik benzetme', ['Kinaye', 'Akrostiş', 'Tekrir'], 'Epik benzetme bir olayı doğa ya da günlük yaşam sahnesiyle uzun uzun karşılaştırır; savaş sahnelerine derinlik katar.'),
  ('Odysseia\'nın ilk dört bölümü olan ve oğlunun babasını aramasını anlatan kısma ne ad verilir?', 'Telemakheia', ['Nekyia', 'Apologoi', 'Mnesterophonia'], 'Telemakheia, Odysseus ortada yokken İthaka\'daki durumu ve Telemakhos\'un yolculuğunu anlatır.'),
  ('Hesiodos\'un tanrıların soyağacını ve evrenin oluşumunu anlattığı eseri hangisidir?', 'Theogonia', ['Eserler ve Günler', 'Herakles\'in Kalkanı', 'Argonautika'], 'Theogonia, Khaos\'tan başlayıp Gaia, Uranos, Kronos ve Zeus\'a uzanan soy kütüğünü anlatır.'),
  ('Hesiodos\'un \'Eserler ve Günler\' adlı şiirinde kime seslenilir?', 'Kardeşi Perses\'e', ['Zeus\'a', 'Oğlu Telemakhos\'a', 'Kralı Alkinoos\'a'], 'Hesiodos, miras konusunda kardeşiyle anlaşmazlık yaşamış ve şiiri ona çalışmayı ve adaleti öğütlemek için yazmıştır.'),
  ('Hesiodos\'a göre ilk kadın olan ve küpün (pithos) kapağını açarak dünyaya kötülükleri yayan figür kimdir?', 'Pandora', ['Hera', 'Gaia', 'Medusa'], 'Zeus\'un Prometheus\'tan intikam almak için Hephaistos\'a yarattırdığı Pandora, \'bütün armağanlar\' anlamına gelir.'),
  ('Hesiodos\'un Theogonia\'sında evrenin başlangıcındaki ilk varlık ya da boşluk hangisidir?', 'Khaos', ['Kosmos', 'Eros', 'Tartaros'], 'Theogonia, Khaos\'un önce var olduğunu söyler; ardından Gaia (Yer), Tartaros ve Eros ortaya çıkar.'),
  ('Yunan şiirinde \'lirik\' adının kaynağı olan ve şiirlerin eşliğinde çalınan çalgı hangisidir?', 'Lyra', ['Aulos', 'Salpinks', 'Tympanon'], 'Lirik şiir, lyra eşliğinde söylenen kişisel duygu şiirleridir; terim bu çalgıdan türemiştir.'),
  ('Elegeia biçimi hangi dize çiftinin birleşiminden oluşur?', 'Hekzametre ve pentametre', ['İki hekzametre', 'Jambik trimetre ve tetrametre', 'İki pentametre'], 'Elegeia, bir hekzametreyi bir pentametrenin izlediği ikili dizelerle kurulur; ağıt, öğüt ve savaş şiirinde kullanılmıştır.'),
  ('Atina\'nın yasa koyucusu olarak da bilinen, toplumsal düzeni şiirlerinde savunan arkaik dönem şairi kimdir?', 'Solon', ['Alkaios', 'Stesikhoros', 'Bakkhylides'], 'Solon, siyasal ve ahlaki görüşlerini elegeia ve jambik dizelerle dile getirmiştir.'),
  ('Termopylai\'de ölen Spartalılar için yazdığı kısa mezar yazısıyla ünlenen, epigram ustası şair kimdir?', 'Simonides', ['Pindaros', 'Alkaios', 'Sappho'], 'Keoslu Simonides\'in epigramları kısalığı ve duygu yoğunluğuyla Batı epigram geleneğinin ilk örnekleri arasındadır.'),
  ('Aşağıdaki lirik biçimlerden hangisi şenliklerde Dionysos\'a söylenen, koronun dairesel dansla okuduğu şarkıyı anlatır?', 'Dithyrambos', ['Epinikion', 'Threnos', 'Hymenaios'], 'Dithyrambos, tragedyanın doğuşuyla ilişkilendirilen koro şarkısıdır; zamanla şölen ve şarap temalı coşkulu anlatımın simgesi olmuştur.'),
  ('Aşağıdaki lirik şiir biçimlerinden hangisi cenaze ve ölüm acısıyla ilgilidir?', 'Threnos', ['Hymenaios', 'Epinikion', 'Skolion'], 'Threnos, yas ve ağıt için söylenen şarkıdır; Pindaros ve Simonides örnekler vermiştir.'),
  ('Geleneğe göre Atina\'da ilk tragedya oyuncusu olarak kabul edilen ve koro dışında ilk kez ayrı bir rolle sahneye çıkan kişi kimdir?', 'Thespis', ['Phrynichos', 'Arion', 'Epigenes'], 'Thespis\'in koroyla konuşan ilk oyuncu olduğu söylenir; İngilizce \'thespian\' (oyuncu) sözcüğü ondan türemiştir.'),
  ('Atina\'da tragedya ve komedya yarışmalarının yapıldığı büyük şenlik hangi tanrı adına düzenlenirdi?', 'Dionysos', ['Apollon', 'Athena', 'Demeter'], 'Büyük Dionysia şenliğinde tragedya ve komedya ozanları yarışır, yargıçlar birinciyi seçerdi.'),
  ('Antik Yunan tiyatrosunda koronun dans ettiği yuvarlak alana ne ad verilir?', 'Orkestra', ['Skene', 'Theatron', 'Parodos'], 'Orkestra \'dans yeri\' demektir; koro burada hareket ederken seyirciler theatron denen basamaklarda oturur.'),
  ('Antik tiyatroda oyuncuların arkasındaki yapıya, sahne arkası ve kostüm değiştirme yeri olarak hizmet eden bölüme ne denirdi?', 'Skene', ['Stasimon', 'Exodos', 'Prologos'], 'Skene, çadır ya da baraka olarak başladı; \'sahne\' sözcüğü bu kelimeden gelir.'),
  ('Antik Yunan tragedyasında koronun sahneye ilk girişte söylediği şarkı hangi adla anılır?', 'Parodos', ['Exodos', 'Stasimon', 'Epeisodion'], 'Parodos, koronun girişini bildirir; sonraki koro şarkıları stasimon, oyunun sonu ise exodos\'tur.'),
  ('Atina\'da bir ozanın yarışmaya sunduğu üç tragedya ile birlikte oynanan kısa ve şakacı oyun hangisidir?', 'Satyr oyunu', ['Mimos', 'Fars', 'Atellana'], 'Tetralogia biçiminde üç trajediye bir satyr oyunu eşlik ederdi; böylece seyirci acıdan sonra güldürüyle rahatlardı.'),
  ('Aiskhylos\'un Yedi Kişi Thebai\'ye Karşı oyununda karşı karşıya gelen kardeşler kimlerdir?', 'Eteokles ve Polyneikes', ['Orestes ve Pylades', 'Agamemnon ve Menelaos', 'Zethos ve Amphion'], 'Oidipus\'un iki oğlu Thebai tahtı yüzünden birbirini öldürür; olay Antigone\'nin öyküsüne zemin hazırlar.'),
  ('Aiskhylos\'un Agamemnon\'unda kehanet gücü olup kimse tarafından inanılmayan Truvalı kadın kimdir?', 'Kassandra', ['Polyxena', 'Andromakhe', 'Hekabe'], 'Apollon\'un laneti yüzünden doğru söylese de inanılmayan Kassandra, saray cinayetini önceden bildirir.'),
  ('Aiskhylos\'un Yalvaranlar oyununda koroyu oluşturan kadınlar kimlerdir?', 'Danaos\'un kızları', ['Agamemnon\'un kızları', 'Amazonlar', 'Maenadlar'], 'Danaidler Mısır\'dan Argos\'a kaçarak amcaoğulları ile zorla evlendirilmekten korunmak ister.'),
  ('Oidipus\'un cevaplayarak Thebai\'yi kurtardığı Sphinks bilmecesinin yanıtı nedir?', 'İnsan', ['Zaman', 'Rüzgâr', 'Ateş'], 'Sabah dört, öğlen iki, akşam üç ayakla yürüyen varlık insandır (emekler, yürür, değnekle yürür).'),
  ('Antigone oyununda Antigone\'nin nişanlısı ve Kreon\'un oğlu kimdir?', 'Haimon', ['Eteokles', 'Teiresias', 'Neoptolemos'], 'Antigone\'nin ölümü üzerine Haimon kendini öldürür; ardından annesi Eurydike de intihar eder.'),
  ('Freud\'un psikanalizde \'Oidipus kompleksi\' adını verdiği kavram hangi eserden esinlenmiştir?', 'Sophokles\'in Kral Oidipus\'u', ['Euripides\'in Medea\'sı', 'Aiskhylos\'un Agamemnon\'u', 'Homeros\'un Odysseia\'sı'], 'Freud, çocuğun anne babaya yönelik bilinçdışı duygularını Oidipus\'un kaderine benzeterek adlandırmıştır.'),
  ('Euripides\'in Hippolytos oyununda Phaidra\'nın mutsuz aşkı kime yöneliktir?', 'Üvey oğlu Hippolytos\'a', ['Kocası Theseus\'un müttefiki Pirithoos\'a', 'Tanrı Apollon\'a', 'Kardeşi Minos\'a'], 'Aphrodite\'nin cezasıyla Phaidra\'ya düşen aşk, bir iftira ve Hippolytos\'un ölümüyle sonuçlanır.'),
  ('Alkestis\'i ölümden geri getiren kahraman kimdir?', 'Herakles', ['Orpheus', 'Theseus', 'Perseus'], 'Herakles Thanatos\'la güreşip Alkestis\'i kurtarır; oyun bu yönüyle trajikomik bir hava taşır.'),
  ('Aristophanes\'in Kurbağalar komedyasında Dionysos ölüler diyarında hangi ozanı geri getirmeyi seçer?', 'Aiskhylos', ['Euripides', 'Sophokles', 'Pindaros'], 'Aiskhylos ile Euripides arasındaki yarışmada Dionysos, Atina\'nın kurtuluşu için ciddi öğütler veren Aiskhylos\'u seçer.'),
  ('Eski Komedya\'da koronun seyirciye doğrudan seslendiği, ozanın görüşlerini dile getirdiği bölüme ne ad verilir?', 'Parabasis', ['Prolog', 'Epilog', 'Stasimon'], 'Parabasis sırasında koro oyunu keser ve ozanın fikirlerini seyirciyle paylaşır; Aristophanes\'te sıkça kullanılır.'),
  ('Aristoteles\'in Retorik\'inde ikna araçları arasında konuşmacının güvenilirliğine dayanan unsur hangisidir?', 'Ethos', ['Pathos', 'Logos', 'Mythos'], 'Ethos konuşmacının karakterine, pathos dinleyicinin duygularına, logos ise akıl yürütmeye dayanır.'),
  ('Herodotos\'a \'tarihin babası\' denmesinin nedeni nedir?', 'Olayları araştırıp nedenleriyle sistemli biçimde anlatan ilk eserin (Historiai) yazarı olması', ['Tanrılar çağının ilk yazarı olması', 'Roma tarihini yazmış olması', 'Yalnız savaş stratejilerini yazması'], 'Herodotos Pers Savaşları\'nı ve bölge halklarını anlatırken kaynaklarını sorgular; \'historia\' sözü araştırma demektir.'),
  ('Herodotos\'un doğduğu antik kent, günümüzde hangi Türk ilinde bulunur?', 'Muğla (Halikarnassos / Bodrum)', ['İzmir', 'Aydın', 'Çanakkale (Truva\'nın bulunduğu il)'], 'Halikarnassos bugünkü Bodrum\'dur; Herodotos\'un buradan olduğu bilinir.'),
  ('Thukydides\'in kitabında Atina demokrasisini öven ünlü konuşma kime aittir?', 'Perikles (cenaze söylevi)', ['Kleon', 'Alkibiades (Atinalı komutan ve devlet adamı)', 'Nikias'], 'Perikles, savaşın ilk yılında ölenler için yaptığı söylevde Atina\'nın özgürlük ve demokrasi anlayışını över.'),
  ('Demosthenes\'in Makedonya kralı Filipos\'a karşı yaptığı konuşmalar hangi adla anılır?', 'Philippika', ['Olynthiaka', 'Peri Stephanou', 'Antidosis'], 'Philippika sözcüğü zamanla sert, suçlayıcı konuşma anlamında \'filipik\' olarak dile geçmiştir.'),
  ('Apollonios Rhodios\'un Argonautika destanı hangi kahramanın serüvenini anlatır?', 'Iason\'un Altın Post\'u aramasını', ['Aineias\'ın Truva\'dan İtalya\'ya yolculuğunu', 'Akhilleus\'un öfkesini', 'Herakles\'in on iki görevini'], 'Iason ve Argonautlar Kolkhis\'e yelken açar; Medea\'nın Iason\'a aşkı destanın en etkileyici yanıdır.'),
  ('Longos\'un \'Daphnis ve Khloe\' adlı eseri hangi türün örneği olarak kabul edilir?', 'Antik Yunan aşk romanı', ['Tragedya', 'Destan', 'Felsefi diyalog'], 'Kır yaşamında büyüyen iki gencin aşkını anlatan eser, antik romanın en bilinen örneklerindendir.'),
  ('Aeneas, yanan Truva\'dan kaçarken babası Anchises\'e nasıl yardım eder?', 'Onu sırtında taşır', ['Onu gemiyle uzağa gönderir', 'Onu bir kayığa bindirir', 'Onu kardeşine emanet eder'], 'Aeneas babasını sırtında, oğlu Ascanius\'u elinden tutarak kaçar; bu görüntü \'pietas\' (görev duygusu) simgesidir.'),
  ('Aeneas\'ı yeraltı dünyasına götürüp rehberlik eden Cumae kâhini hangi adla anılır?', 'Sibylla', ['Pythia', 'Kassandra', 'Kirke'], 'Cumae Sibylla\'sı Aeneas\'a Altın Dal\'ı bulmasını ve yeraltında yol almasını öğütler.'),
  ('Aeneis\'te Aeneas\'ın İtalya\'daki başlıca düşmanı olan Rutul kralı kimdir?', 'Turnus', ['Latinus', 'Evander', 'Mezentius'], 'Turnus, Lavinia ile nişanlı olduğu için Aeneas\'a karşı savaşır ve destanın sonunda ölür.'),
  ('Aeneis\'in başlangıcında ozanın hangi iki şeyi şarkıya dökeceğini söylediği sözcük çifti vardır?', 'Silahlar ve adam', ['Aşk ve ölüm', 'Tanrılar ve insanlar', 'Deniz ve toprak'], '\'Arma virumque cano\' (\'Silahları ve adamı söylüyorum\') dizesi, destanın hem savaş hem kahraman odaklı olduğunu belirtir.'),
  ('Vergilius\'un Georgica adlı eseri hangi konuyu işler?', 'Tarım, hayvancılık ve arıcılık', ['Savaş tarihi', 'Aşk şiiri', 'Hukuk ilkeleri ve mahkeme kuralları'], 'Georgica, dört kitapta çiftçiliği ve doğa ile uyumlu yaşamı öğretici bir şiirle anlatır.'),
  ('Vergilius\'un Eclogae (Bucolica) şiirleri hangi Yunan şairin geleneğini sürdürür?', 'Theokritos\'un', ['Pindaros\'un koro şiirlerinin', 'Homeros\'un', 'Sappho\'nun'], 'Çoban şiiri geleneğini Latinceye taşıyan Eclogae, sonraki Avrupa pastoral şiirini etkilemiştir.'),
  ('Catullus\'un \'Odi et amo\' (Nefret ediyorum ve seviyorum) dizeleri hangi duyguyu anlatır?', 'Aşkta çelişkili duyguları', ['Siyasi öfkeyi', 'Savaş acısını', 'Doğa sevgisini ve kır yaşamını'], 'Çift dizelik epigram, sevgiliye duyulan karşıt duyguların aynı anda yaşanmasını sezdirir.'),
  ('Propertius\'un aşk elegeialarında ilgi odağı olan kadın kimdir?', 'Cynthia', ['Lesbia', 'Corinna', 'Delia'], 'Propertius\'un ilk kitabı Cynthia adlı kadına adanmıştır.'),
  ('Horatius\'un Ars Poetica\'sında şiirin işlevi hangi ikili ile özetlenir?', 'Öğretmek ve hoşa gitmek', ['Korkutmak ve ağlatmak', 'Eleştirmek ve alaya almak', 'Övmek ve yermek'], 'Horatius iyi şiirin hem faydalı (docere) hem de zevk verici (delectare) olması gerektiğini söyler.'),
  ('Livius\'un Ab Urbe Condita adlı eseri neyi anlatır?', 'Roma\'nın kuruluşundan itibaren tarihini', ['Pön Savaşları\'nı', 'Gallia seferlerini', 'İmparatorların yaşamlarını kişisel ayrıntılarla anlatan'], 'Livius, Roma tarihini kuruluştan başlayarak anlatan 142 kitaplık geniş bir eser yazmıştır; çoğu kayıptır.'),
  ('Petronius\'un Satyricon\'u hangi türün örneği sayılır?', 'Hicivli, parodik bir roman', ['Tarım şiiri', 'Destan', 'Felsefi diyalog biçiminde bir öğreti'], 'Satyricon, zengin ve görgüsüz Trimalchio\'nun ziyafetiyle tanınır; Roma toplumunu alaya alan düzyazı-şiir karışımı bir eserdir.'),
  ('Suetonius\'un Oniki Sezar adlı eseri hangi türdedir?', 'Biyografi', ['Destan', 'Tragedya', 'Pastoral şiir'], 'Suetonius, Caesar\'dan Domitianus\'a kadar imparatorların hayatlarını kişisel ayrıntılarla anlatmıştır.'),
  ('Adı bilinen ilk yazar kabul edilen, Akad kralı Sargon\'un kızı olan rahibe kimdir?', 'Enheduanna', ['Şamhat', 'Siduri', 'Ereşkigal'], 'Enheduanna, Ur\'da ay tanrısı Nanna\'nın başrahibesiydi ve İnanna\'ya ilahiler yazdı; adı bilinen ilk yazar sayılır.'),
  ('Sümer ve Akad edebiyatının metinleri hangi yazı sistemiyle kil tabletlere yazılmıştır?', 'Çivi yazısıyla', ['Hiyeroglifle', 'Fenike alfabesiyle', 'Ogham yazısıyla'], 'Çivi yazısı, kamış kalemle yaş kil üzerine kama biçimli işaretler basılarak yazılırdı.'),
  ('Gılgamış Destanı\'nda Gılgamış hangi kenti yönetir?', 'Uruk', ['Babil', 'Ninova', 'Ur'], 'Uruk kralı Gılgamış, üçte ikisi tanrı, üçte biri insan olarak betimlenir.'),
  ('Gılgamış ile Enkidu\'nun birlikte öldürdükleri Sedir Ormanı bekçisinin adı nedir?', 'Humbaba', ['Anzu', 'Tiamat', 'Kingu'], 'İki kahraman ünlü olmak için Humbaba\'yı öldürür; bu cesaret ve kibrin tanrılarca bedeli ödenir.'),
  ('Gılgamış, İştar\'ın evlilik önerisini reddedince İştar\'ın gönderdiği felaket nedir?', 'Göğün Boğası', ['Büyük kuraklık', 'Zehirli yılanlar', 'Savaş tanrısı'], 'Gılgamış ile Enkidu boğayı öldürür; sonuçta tanrılar Enkidu\'nun ölümüne karar verir.'),
  ('Gılgamış, Enkidu\'nun ölümünden sonra ne yapmaya karar verir?', 'Ölümsüzlüğün sırrını aramaya', ['Tahttan çekilmeye', 'Tanrılara karşı savaş açmaya ve Uruk\'tan ayrılmaya', 'Babil\'e göç etmeye'], 'Dostunun ölümü Gılgamış\'ı ölümlülük gerçeğiyle yüzleştirir; Utnapiştim\'i bulmak için uzun bir yolculuğa çıkar.'),
  ('Gılgamış\'a \'Dünyanın tadını çıkar, çocuğunu sev, karını kucakla\' diyen meyhaneci kadın kimdir?', 'Siduri', ['Şamhat', 'İştar', 'Aruru'], 'Siduri, ölümlü insanın ömrünü yaşamaktan alacağı hazları öğütler; Gılgamış bu öğüdü kabul etmez.'),
  ('Gılgamış, Utnapiştim\'in sınavında neyi başaramaz?', 'Altı gün yedi gece uykusuz kalmayı', ['Bir ejderhayı tek başına öldürmeyi', 'Denizi geçmeyi', 'Bir bilmeceyi çözmeyi'], 'Gılgamış uyuyakalır; böylece ölümsüzlüğü hak edemediği gösterilir.'),
  ('Gılgamış\'ın bulduğu ölümsüzlük bitkisini eve dönerken kim çalar?', 'Bir yılan', ['Bir kartal', 'Kayıkçı Urşanabi', 'Enkidu\'nun ruhu'], 'Gılgamış banyo yaparken yılan bitkiyi alır; yılanın deri değiştirmesi gençleşme sembolüne bağlanır.'),
  ('Mısır Ölüler Kitabı\'nın temel amacı nedir?', 'Ölünün öbür dünyada güvenle geçmesi için büyü ve dualar sağlamak', ['Firavunun savaşlarını anlatmak', 'Tarım takvimi düzenlemek', 'Tapınak ritüeli kuralları koymak'], 'Ölüler Kitabı mezara konan papirüslerde yer alan büyü, dua ve sözlerin derlemesidir.'),
  ('Ölüler Kitabı\'ndaki \'kalbin tartılması\' sahnesinde kalp neyle karşılaştırılır?', 'Maat\'ın tüyüyle', ['Altın bir ağırlıkla', 'Bir taşla', 'Osiris\'in tacıyla'], 'Kalp tüyden ağırsa yaratık Ammit onu yer; hafifse ölü Osiris\'in önünde aklanır.'),
  ('Osiris efsanesinde Osiris\'i öldüren ve parçalayan tanrı kimdir?', 'Set', ['Horus', 'Anubis', 'Thoth'], 'Isis, parçalanan kocasının bedenini toplar ve Horus\'u doğurur; Horus babasının intikamını alır.'),
  ('Jean-François Champollion\'un 1822\'de hiyeroglifleri çözmesini sağlayan buluntu nedir?', 'Rosetta Taşı', ['Narmer Paleti', 'Palermo Taşı', 'Hammurabi Steli'], 'Üç yazıyla (hiyeroglif, demotik, Yunanca) yazılmış taş, çözümün anahtarı olmuştur.'),
  ('Eski Ahit\'in Tevrat (Pentateuk) olarak anılan ilk beş kitabı geleneksel olarak kime atfedilir?', 'Musa\'ya', ['Davud\'a', 'Süleyman\'a', 'Ezra\'ya'], 'Tekvin, Çıkış, Levililer, Sayılar ve Tesniye\'den oluşan bölüm geleneksel olarak Musa\'ya atfedilir.'),
  ('Mezmurlar Kitabı kaç ilahiden oluşur ve geleneksel olarak kime atfedilir?', '150 ilahi; Davud\'a', ['75 ilahi; Musa\'ya', '300 ilahi; Süleyman\'a', '12 ilahi; Yeremya\'ya'], 'Mezmurlar, ibadet ve yakarış şiirlerinin derlemesidir; çoğunluğu Davud\'a bağlanır.'),
  ('Eyüp Kitabı\'nın temel sorusu nedir?', 'Doğru insanın neden acı çektiği', ['Kralların nasıl yönetmesi gerektiği', 'İbadetin kuralları', 'Dünyanın nasıl yaratıldığı'], 'Eyüp, başına gelen felaketleri anlamaya çalışırken dostlarının \'günah\' açıklamalarını reddeder.'),
  ('Neşideler Neşidesi (Ezgiler Ezgisi) hangi tür metindir?', 'Aşk şiiri', ['Hukuk metni', 'Peygamberlik duyurusu', 'Soy kütüğü'], 'Âşıkların birbirine seslendiği şiirler bütünü, hem insan aşkı hem alegorik ilahi aşk olarak yorumlanmıştır.'),
  ('Rut Kitabı\'nın başlıca teması nedir?', 'Gelinin kaynanasına sadakati', ['Kralın ihaneti', 'Büyük bir savaş', 'Tufan ve kurtuluş temalı bir peygamber öyküsü'], 'Moablı Rut, kaynanası Naomi\'yi bırakmaz; \'Nereye gidersen ben de gelirim\' sözü sadakat simgesidir.'),
  ('Hint düşünce ve edebiyatının en eski metinleri olan Vedalar kaç ana bölümden oluşur ve en eski olanı hangisidir?', 'Dört; Rigveda', ['Üç; Atharvaveda', 'Beş; Samaveda', 'İki; Yajurveda'], 'Rigveda, Samaveda, Yajurveda ve Atharvaveda\'dan en eskisi ilahilerden oluşan Rigveda\'dır.'),
  ('Rigveda\'nın içeriği başlıca hangi tür metinlerden oluşur?', 'Tanrılara yönelik ilahiler', ['Savaş öyküleri', 'Hukuk kuralları ve kral buyrukları', 'Masal ve fablar'], 'Agni, Indra ve Soma gibi tanrılara yazılmış 1000\'den fazla ilahi içerir.'),
  ('Upanişadlar Vedaların hangi yönünü temsil eder?', 'Felsefi ve metafizik kısmını', ['Savaş kurallarını', 'Takvim bilgilerini ve ritüel kurallarını', 'Tıp bilgilerini'], 'Upanişadlar \'Vedaların sonu\' (Vedanta) olarak anılır ve atman-brahman ilişkisini işler.'),
  ('Upanişadlar felsefesinde \'atman\' kavramı neyi ifade eder?', 'Bireyin değişmez iç özünü', ['Dünyevi zenginliği', 'Tanrıya yapılan adağı', 'Doğum ve ölüm döngüsünü'], 'Atman, bireyin ölümsüz özüdür ve nihayetinde Brahman ile aynı kabul edilir.'),
  ('Mahabharata\'nın yazarı geleneksel olarak kim sayılır?', 'Vyasa', ['Valmiki', 'Kalidasa', 'Tulsidas'], 'Vyasa\'nın destanı söylediği ve Ganeşa\'nın yazdığı anlatılır; eser tek yazarlı değil, uzun sürede biçimlenmiştir.'),
  ('Mahabharata dünya edebiyatında hangi özelliğiyle bilinir?', 'En uzun destanlardan biri olması', ['En kısa destan olması', 'İlk yazılı roman olması', 'İlk Sanskrit komedyası olarak kabul edilmesi'], 'Yaklaşık yüz bin dörtlükten (şloka) oluşan eser, İlyada ve Odysseia\'nın birleşiminden çok daha uzundur.'),
  ('Mahabharata\'da Pandavalar\'ın ortak eşi olan kadın kimdir?', 'Draupadi', ['Sita', 'Kunti', 'Gandhari'], 'Draupadi, Arjuna\'nın okçuluk yarışmasını kazanmasıyla beş kardeşin eşi olur.'),
  ('Mahabharata\'da Kurukşetra savaşı kaç gün sürer?', '18 gün', ['7 gün', '40 gün', '100 gün'], 'Savaş on sekiz gün sürer ve Kaurava ordusu yok olur; yalnız birkaç kişi sağ kalır.'),
  ('Bhagavad Gita\'nın başlıca öğüdü hangisidir?', 'Görevini sonucuna bağlanmadan yapmak', ['Savaştan kaçınmak', 'Servet biriktirmek', 'Dünyadan elini ayağını çekip inzivaya çekilmek'], 'Krişna Arjuna\'ya dharma gereği savaşması gerektiğini, eylemin meyvelerine bağlanmadan yapılmasını öğütler.'),
  ('Gita\'da Krişna, Arjuna\'nın hangi rolünü üstlenir?', 'Savaş arabasının sürücüsü ve öğütçüsü', ['Düşman komutanı', 'Kâhini', 'Kardeşi'], 'Savaş alanında Arjuna\'nın tereddütünü gideren Krişna, Gita öğretisini sunar.'),
  ('Ramayana\'nın yazarı kabul edilen ve \'ilk şair\' (adi kavi) diye anılan kişi kimdir?', 'Valmiki', ['Vyasa', 'Kalidasa', 'Bhasa'], 'Valmiki\'nin bir kuşun ölümüne acıyıp şloka biçimini bulduğu söylenir.'),
  ('Ramayana\'da Sita\'yı kaçıran Lanka kralı Ravana\'nın en ayırt edici görünüm özelliği nedir?', 'On başlı olması', ['Üç gözlü olması', 'Altı kollu olması', 'Kanatlı olması'], 'Ravana, on başı ve yirmi koluyla bilinen güçlü bir rakşasa (iblis) kralıdır.'),
  ('Ramayana\'da Sita\'yı bulmak için Lanka\'ya uçarak giden maymun kahraman kimdir?', 'Hanuman', ['Sugriva', 'Jambavan', 'Angada'], 'Hanuman Rama\'nın sadık yardımcısıdır; Hindistan\'da güç ve bağlılık simgesidir.'),
  ('Ramayana\'da Rama\'nın kardeşi olup sürgüne onunla giden kişi kimdir?', 'Lakshmana', ['Bharata', 'Shatrughna', 'Vibhishana'], 'Lakshmana, ağabeyine ve Sita\'ya yoldaşlık etmek için sürgüne katılır.'),
  ('Diwali bayramı, Ramayana\'daki hangi olayla ilişkilendirilir?', 'Rama\'nın sürgünden Ayodhya\'ya dönüşü', ['Sita\'nın kaçırılması ve Ravana\'nın ölümü', 'Lanka\'nın kuruluşu', 'Hanuman\'ın doğumu'], 'Ayodhya halkı dönüşünü kandil yakarak kutlamış, bayram bu geleneği sürdürür.'),
  ('Panini\'nin Aştadhyayi\'si hangi alanda Hint düşüncesinin dünya çapındaki başarısı sayılır?', 'Sanskrit dilbilgisi', ['Tıp', 'Astronomi ve takvim hesapları', 'Hukuk'], 'Yaklaşık dört bin kısa kural (sutra) içeren eser, dilbilgisini sistemli biçimde betimleyen en eski örneklerdendir.'),
  ('Hitopadesa, hangi eserden alınan öykülerle düzenlenmiş bir öğüt derlemesi kabul edilir?', 'Pançatantra\'dan', ['Mahabharata\'daki öğüt bölümlerinden', 'Rigveda\'dan', 'Gılgamış\'tan'], 'Hitopadesa, hayvan masallarıyla çıkar yolu gösteren öğüt kitabıdır ve Pançatantra\'nın başka bir düzenlemesidir.'),
  ('Tulsidas\'ın Ramcharitmanas\'ı hangi dilde yazılmıştır ve neyi yeniden anlatır?', 'Avadhi lehçesinde, Ramayana\'yı', ['Sanskritçe, Mahabharata\'yı kısaltarak', 'Farsça, Şehname\'yi', 'Bengalce, Gita\'yı'], '16. yüzyılda halk diliyle yazılan eser Ramayana\'yı geniş kitlelere ulaştırmıştır.'),
  ('Mirabai\'nin şiirlerinde yücelttiği tanrı kimdir?', 'Krişna', ['Şiva', 'Brahma', 'Hanuman'], 'Mirabai, Rajasthan prensesi olarak Krişna\'ya duyduğu aşkı bhajan olarak söylemiştir.'),
  ('Urdu şiirinin 19. yüzyıldaki en büyük şairlerinden biri sayılan, Delhi\'li Farsça ve Urdu divan sahibi kimdir?', 'Mirza Gâlib', ['Muhammed İkbal', 'Rabindranath Tagore', 'Premchand'], 'Gâlib, ince düşünce ve acı mizahla yazdığı gazelleriyle tanınır.'),
  ('Rabindranath Tagore\'un bestelediği şarkılardan hangisi Hindistan\'ın milli marşı olmuştur?', 'Jana Gana Mana', ['Vande Mataram', 'Sare Jahan Se Accha', 'Amar Sonar Bangla'], 'Tagore\'un Bengalce şarkısı Hindistan\'ın milli marşıdır; Amar Sonar Bangla ise Bangladeş\'in marşıdır.'),
  ('Jataka öyküleri neyi konu alır?', 'Buddha\'nın önceki yaşamlarını', ['Buddha\'nın ölümünü', 'Krişna\'nın gençliğini ve çobanlık yıllarını', 'Şiva\'nın savaşlarını'], 'Jatakalar, Buddha\'nın hayvan ve insan olarak geçmiş yaşamlarındaki fedakârlıklarını anlatan öğretici öykülerdir.'),
  ('Theravada Budizmi\'nin kutsal metinleri hangi dilde korunmuştur?', 'Pali', ['Sanskrit', 'Tibetçe', 'Çince'], 'Tipitaka\'nın en eksiksiz hali Pali dilindedir; Sanskrit ve Çince koleksiyonlar da vardır.'),
  ('Konfüçyüs düşüncesinin temel kavramlarından \'ren\' neyi ifade eder?', 'İnsanlık, iyilikseverlik', ['Savaşçılık', 'Zenginlik', 'Büyüsel güç ve doğaüstü yetenek'], 'Ren, insanın başkalarına karşı gösterdiği saygı ve şefkat erdemidir.'),
  ('Konfüçyüs geleneğinde \'Beş Klasik\' arasında yer alan ve şiir antolojisi olan eser hangisidir?', 'Shijing', ['Yijing', 'Liji', 'Chunqiu'], 'Shijing (Şiirler Kitabı) 305 şiirden oluşan en eski Çin şiir derlemesidir.'),
  ('Yijing (Değişimler Kitabı) hangi sembol sistemine dayanır?', '64 heksagram', ['12 hayvan burcu', '28 yıldız evi', '108 işaret'], 'Yijing, çizgilerden oluşan 64 heksagram ve bunların yorumlarına dayanan fal ve felsefe metnidir.'),
  ('Çin\'de memur sınavlarının (keju) uzun yüzyıllar boyunca temeli hangi metinlere dayandırılmıştır?', 'Konfüçyüsçü klasiklere', ['Taoist metinlere', 'Budist sutralara', 'Askerî el kitaplarına ve strateji metinlerine'], 'Sınavlar adayların klasik metinleri ezbere bilmesini ve yorumlamasını gerektirirdi.'),
  ('Daodejing hangi düşünürün adıyla anılır?', 'Laozi', ['Zhuangzi', 'Mozi', 'Han Feizi'], 'Daodejing, yaklaşık 5000 karakterlik 81 kısa bölümden oluşan Taoizm\'in temel metnidir.'),
  ('Sun Tzu\'ya atfedilen Savaş Sanatı kaç bölümden oluşur?', 'On üç', ['Yedi', 'Yirmi bir', 'Kırk iki'], 'Savaş Sanatı, strateji ve istihbaratı ele alan on üç kısa bölümden oluşur.'),
  ('Sun Tzu\'ya göre en üstün başarı biçimi nedir?', 'Savaşmadan düşmanın direncini kırmak', ['En çok esir almak', 'Şehirleri yakmak', 'Düşmanı uzun süre kuşatıp aç bırakmak'], 'Sun Tzu\'ya göre savaşmadan kazanmak, bütün zaferlerin en üstünüdür.'),
  ('Çin\'in en eski şiir derlemesi olan Shijing\'de kaç şiir vardır?', '305', ['50', '108', '1001'], 'Shijing, halk şarkıları, saray şiirleri ve ilahiler içerir; geleneksel olarak Konfüçyüs\'ün derlediğine inanılır.'),
  ('Qu Yuan\'ın anısı Çin\'de hangi festivalle yaşatılır?', 'Ejderha Kayığı (Duanwu) Festivali', ['Fener Festivali', 'Ay Festivali', 'Qingming'], 'Halkın nehre pirinç topları atarak şairin bedenini balıklardan korumak istediği anlatılır.'),
  ('\'Kızıl Odanın Rüyası\' romanı hangi ailenin çöküşünü anlatır?', 'Jia ailesinin', ['Liu ailesinin', 'Wang ailesinin', 'Li ailesinin'], 'Cao Xueqin\'in Qing dönemi romanı, Jia Baoyu ve Lin Daiyu\'nun aşkıyla ailenin yıkımını işler.'),
  ('Japon mitolojisi ve imparatorluk soyunun anlatıldığı, 712\'de derlenen en eski Japon yazılı eseri hangisidir?', 'Kojiki', ['Man\'yoshu', 'Kokinshu', 'Heike Monogatari'], 'Kojiki, yaratılış efsanelerini ve imparatorluk soyağacını içerir; Nihon Shoki ise 720\'de derlenen resmî tarihtir.'),
  ('Waka (tanka) şiir biçimi hangi hece düzenine sahiptir?', '5-7-5-7-7', ['5-7-5-7-5-7-7', '7-7-7', '3-5-3'], 'Otuz bir heceli tanka, Japon klasik şiirinin ana biçimidir; haiku ise ilk üç dizesinden doğmuştur.'),
  ('Chikamatsu Monzaemon hangi iki sahne türü için oyun yazmıştır?', 'Bunraku (kukla) ve Kabuki', ['Noh ve Kyogen', 'Rakugo ve Kodan', 'Gagaku ve Bugaku'], 'Chikamatsu, \'Japon Shakespeare\'i\' olarak anılır; \'Sonezaki Aşk İntiharları\' en ünlü eseridir.'),
  ('Akutagawa Ryunosuke\'nin \'Rashomon\' ve \'Çalılıkta\' hikâyeleri hangi sinema yönetmeninin filmine kaynaklık etmiştir?', 'Akira Kurosawa', ['Yasujiro Ozu', 'Kenji Mizoguchi', 'Hayao Miyazaki'], 'Kurosawa\'nın 1950 tarihli Rashomon filmi, aynı olayın farklı anlatımlarına dayanan öyküden esinlenmiştir.'),
  ('Oe Kenzaburo\'nun hangi yılda Nobel Edebiyat Ödülü\'nü aldığı bilinir?', '1994', ['1968', '1981', '2002'], 'Kenzaburo Oe, ikinci Japon Nobel edebiyat ödüllüsüdür; ilkini Kawabata 1968\'de almıştı.'),
  ('Kore alfabesi Hangul\'un yaratılışı hangi hükümdara bağlanır?', 'Kral Sejong', ['Kral Gojong', 'Kral Taejo', 'Kral Seondeok'], 'Sejong, halkın kolay okuyup yazabilmesi için 1443-1446 yıllarında Hangul\'u hazırlattı.'),
  ('Tibet\'in ulusal destanı olan eser hangisidir?', 'Gesar Destanı', ['Manas', 'Kalevala', 'Şehname'], 'Ling Kralı Gesar\'ın savaşlarını anlatan sözlü destan Tibet ve Orta Asya\'da yaşar.'),
  ('Moğolların Gizli Tarihi hangi hükümdarın yaşamını anlatır?', 'Cengiz Han', ['Kubilay Han', 'Timur', 'Attila'], '13. yüzyılda Moğolca yazılan eser, Cengiz Han\'ın soyunu ve yükselişini anlatır.'),
  ('Şehname yaklaşık kaç beyitten oluşur?', 'Elli bin', ['Beş bin', 'Yirmi bin', 'Yüz yirmi bin'], 'Firdevsi\'nin Şehname\'si yaklaşık elli bin beyitlik dev bir mesnevidir.'),
  ('Şehname\'nin doğduğu Tus şehri bugünkü hangi ülkede ve bölgededir?', 'İran\'da Horasan bölgesi', ['Irak\'ta Bağdat ve çevresinde', 'Afganistan\'da Kabil', 'Türkiye\'de Erzurum'], 'Firdevsi Tus\'ta doğmuş, eserini 1010 dolaylarında tamamlamıştır.'),
  ('Şehname\'de Zalim Dahhak\'ın omuzlarında ne vardır?', 'İnsan beyniyle beslenen iki yılan', ['Altın bir tac', 'Kanatlar', 'Ateş yutan ejderha'], 'Beyin isteyen yılanlar yüzünden binlerce genç ölür; demirci Kave isyan eder.'),
  ('Demirci Kave, Dahhak\'a karşı ayaklanırken neyi bayrak yapar?', 'Deri önlüğünü', ['Bir kılıç', 'Bir yılan derisi', 'Bir tuğra'], 'Kave\'nin önlüğü \'Derefş-i Kaviyani\' adıyla İran\'ın kutsal sancağına dönüşür.'),
  ('Şehname\'de Zal\'ı doğduğunda saçı beyaz diye dağa bırakılan çocuğu kim büyütür?', 'Simurg', ['Anka kuşu', 'Rahş', 'Kave'], 'Efsanevi kuş Simurg onu yavrularıyla birlikte büyütür; sonra Zal babası tarafından geri alınır.'),
  ('Rüstem\'in efsanevi atının adı nedir?', 'Rahş', ['Şebdiz', 'Düldül', 'Bucephalus'], 'Rahş, Rüstem\'le birlikte pek çok maceraya girer ve bütün Şehname\'de sadık dost olarak betimlenir.'),
  ('Şehname\'de İran ile Turan arasındaki savaşların baş düşmanı olan Turan hükümdarı kimdir?', 'Afrasiyab', ['Dahhak', 'Mahmud', 'Kobad'], 'Afrasiyab, Siyavuş\'un ölümünden ve birçok savaştan sorumlu en büyük düşmandır.'),
  ('Feridüddin Attar\'ın veliler hakkında derlediği ünlü düzyazı eseri hangisidir?', 'Tezkiretü\'l-Evliya', ['Mantıku\'t-Tayr', 'Muselletname', 'İlahiname'], 'Attar\'ın bu eseri, Bayezid-i Bistami gibi büyük sufilerin yaşam öykülerini aktarır.'),
  ('Hafız mahlasının anlamı nedir?', 'Kur\'an\'ı ezbere bilen', ['Güzel ve etkileyici konuşan', 'Şiraz\'lı', 'Sır tutan'], 'Şair, Kur\'an\'ı ezbere bildiği için bu adı almış, Şiraz\'da yaşamıştır.'),
  ('Mevlana\'nın şiirine ve müziğe yönelişine yol açan, Divan-ı Kebir\'in \'Divan-ı Şems\' adıyla da anıldığı derviş kimdir?', 'Şems-i Tebrizi', ['Sultan Veled', 'Hüsameddin Çelebi', 'Selahaddin Zerkubi'], 'Şems ile karşılaşma Mevlana\'yı şiire ve müziğe yöneltmiştir; Divan-ı Kebir \'Divan-ı Şems\' diye de anılır.'),
  ('Cahiliye dönemi Arap şairlerinin şiirlerini yarıştırdıkları ve dinletiler yaptıkları büyük panayır hangisidir?', 'Ukaz Panayırı', ['Arafat Panayırı', 'Hira Panayırı', 'Basra Panayırı'], 'Mekke çevresinde yılda bir kurulan Ukaz\'da şairler kasidelerini okur, kabilelerin ünü şiirle yayılırdı.'),
  ('Arap şiirinin ilk büyük şairi sayılan ve \'Dur ağlaşalım\' dizesiyle başlayan muallakası ile ünlü kişi kimdir?', 'İmruülkays', ['Tarafe', 'Antara', 'Lebid'], 'İmruülkays, yıkık yurdun ve sevgilinin anılmasıyla başlayan kaside kalıbını örnekleyen şairdir.'),
  ('Antara bin Şeddad\'ın şiirlerinde öne çıkan iki tema hangisidir?', 'Kahramanlık ve sevgilisi Abla\'ya aşk', ['Şarap ve eğlence', 'Zenginlik, ticaret ve kervan yolculuğu', 'Din ve zühd'], 'Siyah köle annesinden doğan Antara, cesaretiyle özgürlüğünü kazanmış, Abla\'ya duyduğu aşkı şiirlerine yansıtmıştır.'),
  ('Cahiliye şairi Hansa\'nın şiirleri hangi türde yoğunlaşır?', 'Kardeşi Sahr için yazdığı mersiyeler', ['Aşk şiiri', 'Hiciv', 'Savaş şiiri'], 'Hansa, kardeşinin ölümüne yazdığı ağıtlarla Arap mersiye geleneğinin en ünlü ismi sayılır.'),
  ('Hz. Peygamber\'in şairi olarak anılan Medineli şair kimdir?', 'Hassan bin Sabit', ['Lebid', 'Kâb bin Züheyr', 'Ahtal'], 'Hassan, Müslümanları savunan şiirler yazmıştır.'),
  ('Abbasi döneminde şarap temalı şiirlere (hamriyyat) öncülük eden şair kimdir?', 'Ebu Nuvas', ['Ebu\'l-Atahiye', 'Mütenebbi', 'Maarri'], 'Ebu Nuvas, Bağdat\'ın eğlence hayatını ve şarabı övdüğü şiirleriyle tanınır.'),
  ('Ebu\'l-Atahiye\'nin şiirleri hangi tür temalarla öne çıkar?', 'Zühd ve ölüm düşüncesi', ['Şarap ve eğlence meclisleri', 'Savaş ve övgü', 'Aşk ve gül'], 'Zühdiyyat adı verilen şiirleri dünya nimetlerinin geçiciliğini anlatır.'),
  ('İbnü\'l-Mukaffa\'nın Kelile ve Dimne\'yi Arapçaya doğrudan hangi dildeki metinden çevirdiği kabul edilir?', 'Pehlevi (Orta Farsça)', ['Sanskritçe (Hint klasik dili)', 'Yunanca', 'Süryanice'], 'Pançatantra\'nın Sanskritçe kaynaklı Pehlevice versiyonu İbnü\'l-Mukaffa tarafından Arapçaya çevrilip kendi üslubuyla yeniden yazılmıştır.'),
  ('Cahiz\'in \'Kitabü\'l-Buhala\' adlı eseri neyi konu alır?', 'Cimri insanların komik öykülerini', ['Hayvanların biyolojisini', 'Bir hükümdarın yaşamını ve savaşlarını', 'Savaşlardaki taktikleri'], 'Cahiz, esprili ve gözleme dayalı üslubuyla Abbasi toplumunun portrelerini sunar.'),
  ('İbn Haldun\'un Mukaddime\'sinde toplumların yükselişi ve çöküşünü açıklamak için kullandığı temel kavram nedir?', 'Asabiyet', ['Kader', 'Servet ve zenginlik', 'Ritüel'], 'İbn Haldun, toplumsal bağlılık ve dayanışmayı ifade eden asabiyetin devletlerin kuruluş ve çöküşünü belirlediğini savunur.'),
  ('İbn Battuta\'nın Rihle\'si hangi türdendir?', 'Seyahatname', ['Mesnevi', 'Makame', 'Mersiye'], 'Faslı gezgin, 14. yüzyılda yaklaşık otuz yıl süren yolculuğunu bu eserde anlatır.'),
  ('Binbir Gece Masalları\'nın Avrupa dillerine ilk çevirisi hangi yazara aittir?', 'Antoine Galland', ['Richard Burton', 'Edward Lane', 'Jorge Luis Borges'], 'Galland, 1704\'ten itibaren Fransızca çevirisini yayımlayarak masalları Avrupa\'ya tanıtmış ve kendi anlatılarını da eklemiştir.'),
  ('Binbir Gece Masalları\'ndaki \'Sinbad\' hikâyeleri kaç yolculuk içerir?', 'Yedi', ['Beş', 'Dokuz', 'On iki'], 'Denizci Sinbad, yedi yolculukta tehlikeli deniz yaratıkları, devler ve hazinelerle karşılaşır.'),
  ('Arap dünyasında 19. yüzyıl kültürel uyanışını ve yenileşmesini anlatmak için kullanılan terim hangisidir?', 'Nahda', ['Hicret', 'Tanzimat', 'Rönesans'], 'Nahda (\'uyanış\') Mısır ve Lübnan merkezli matbaa, gazete ve çeviri hareketiyle gelişen kültürel yenilenmedir.'),
  ('\'Şairler Prensi\' (Emirü\'ş-şuara) unvanıyla anılan Mısırlı şair kimdir?', 'Ahmed Şevki', ['Hafız İbrahim', 'Cibran Halil Cibran', 'Nizar Kabbani'], 'Ahmed Şevki, klasik Arap şiirini yeniledi ve tiyatro eserleri de yazdı.'),
  ('Halil Cibran\'ın İngilizce yazdığı ve dünyada çok tanınan eseri hangisidir?', 'Peygamber', ['Kırık Kanatlar', 'Gerçeğin Peşinde', 'Ruhların Gölgesi'], 'Peygamber 1923\'te yayımlanmış, aşk, evlilik ve ölüm gibi konularda kısa öğütlerden oluşur.'),
  ('Necib Mahfuz\'un Kahire Üçlemesi hangi aile üzerinden Mısır toplumunu anlatır?', 'Ahmed Abdülcevad ailesi', ['Halife ailesi', 'Hamdan ailesi', 'Mamluk ailesi'], 'Üçleme, 20. yüzyıl başından II. Dünya Savaşı\'na kadar üç kuşağın yaşamını izler.'),
  ('Mahmud Derviş\'in şiirlerinde öne çıkan temalar hangileridir?', 'Sürgün, vatan özlemi ve kimlik', ['Saray hayatı ve hükümdar övgüsü', 'Zenginlik', 'Büyücülük'], 'Filistinli şair, vatan ve sürgün temalarını çağdaş Arap şiirine taşımıştır.'),
  ('Samed Behrengi\'nin \'Küçük Kara Balık\' hikâyesi hangi türdendir?', 'Alegorik çocuk hikâyesi', ['Destan', 'Mesnevi', 'Kaside'], 'Küçük balığın denize ulaşma çabası, özgürlük ve başkaldırının simgesi olarak okunur.'),
  ('Zerdüştlüğün kutsal kitabı hangisidir?', 'Avesta', ['Veda', 'Tripitaka', 'Granth'], 'Avesta, Eski Avestaca ve Genç Avestaca bölümlerinden oluşan Zerdüşt kutsal metinleridir.'),
  ('Nala ile Damayanti ve Savitri ile Satyavan öyküleri hangi destanın içinde yer alır?', 'Mahabharata', ['Ramayana', 'Rigveda', 'Pançatantra'], 'Bu iki aşk ve sadakat öyküsü Mahabharata\'nın ana anlatısına eklenmiş alt hikâyelerdir.'),
  ('Mali İmparatorluğu\'nun kurucusunu anlatan Batı Afrika destanı hangisidir?', 'Sundiata Destanı', ['Beowulf', 'Kalevala', 'Gesar'], 'Sundiata Keita\'nın sakat çocukluktan imparatorluk kurucusu oluşunu anlatan destan, gelenekçi anlatıcılar (griot) tarafından aktarılır.'),
  ('Batı Afrika\'da destanları ve soy kütüklerini sözlü olarak aktaran anlatıcılara ne ad verilir?', 'Griot', ['Rhapsodos', 'Aşık', 'Skald'], 'Griotlar, hem tarihçi hem ozan hem müzisyen olarak toplumsal belleği taşır.'),
  ('Homeros\'ta \'kleos\' kavramı neyi anlatır?', 'Ölümden sonra da yaşayan ün ve şöhret', ['Tanrılara körü körüne itaat ve kurban', 'Mal mülk', 'Doğum hakkı'], 'Kahramanlar kısa ama şanlı bir ömrü, uzun ama sıradan bir yaşama tercih edebilir; Akhilleus\'un seçimi buna örnektir.'),
  ('Yunan düşüncesinde \'moira\' neyi ifade eder?', 'Tanrıların bile tam aşamadığı kader payı', ['Tanrılara sunulan değerli armağan ve kurban', 'Bir tür savaş çığlığı', 'Kral yetkisi'], 'İlyada ve tragedyalarda kader, kahramanın seçimleriyle birleşerek trajik akışı belirler.'),
  ('Truva kalıntılarının Hisarlık\'ta aranmasına dayalı kazılara 1870\'lerde başlayan arkeolog kimdir?', 'Heinrich Schliemann', ['Arthur Evans', 'Howard Carter', 'Leonard Woolley'], 'Schliemann\'ın Homeros\'a dayalı kazıları, Troya\'nın tarihsel varlığı tartışmalarını güçlendirmiştir.'),
  ('Antik tiyatroda tanrıyı sahneye indirmek ya da kaldırmak için kullanılan vinç düzeneğine ne ad verilir?', 'Mekhane', ['Ekkyklema', 'Skene', 'Orkestra'], 'Latince \'deus ex machina\' deyimi bu düzenekten türemiştir.'),
  ('Augustus dönemi Latin edebiyatının \'Altın Çağ\'ında hangi isim yer alır?', 'Vergilius', ['Ennius', 'Petronius', 'Lucanus'], 'Altın Çağ, Cicero ve Augustus dönemini kapsar; Vergilius, Horatius ve Ovidius bu dönemin şairleridir.'),
  ('İlyada\'da tanrıların da taraf tutarak kendi aralarında çarpıştığı bölüme ne ad verilir?', 'Tanrılar savaşı (Theomakhia)', ['Gemiler Katalogu (ikinci bölüm)', 'Cenaze oyunları', 'Dolonia'], 'Yirmi birinci bölümde Athena, Ares\'i ve Aphrodite\'yi alt eder; Hera, Artemis\'e ders verir.'),
  ('Aineias\'ın Aphrodite\'nin oğlu olduğu bilgisi, hangi sonraki esere zemin hazırlamıştır?', 'Vergilius\'un Aeneis\'ine', ['Apollonios\'un Argonautika\'sına', 'Theogonia\'ya', 'Lysistrata\'ya'], 'Aineias İlyada\'da Truvalıların en önemli kahramanlarından biri olarak anılır; sonradan Roma\'nın atası olarak yeniden yazılır.'),
  ('Odysseus, Phaiakların gemisiyle İthaka\'ya getirildiğinde hangi durumdadır?', 'Uykudayken kıyıya bırakılmıştır', ['Hasta bir şekilde taşınmıştır', 'Yara almıştır', 'Bilinci açıktır ve karşılanmıştır'], 'Phaiaklar onu armağanlarıyla birlikte uyurken kıyıya bırakır; Poseidon sonradan Phaiak gemisini taşa çevirir.'),
  ('Odysseus, Ogygia\'dan ayrılırken denizi aşmak için neye binmiştir?', 'Kendi yaptığı sala', ['Phaiak gemisine', 'Poseidon\'un arabasına', 'Bir yunus sırtına'], 'Kalypso\'nun verdiği aletlerle beş gün çalışarak bir sal yapar; Poseidon bir fırtınayla sali parçalar.'),
  ('Odysseia\'nın sonunda talip ailelerinin intikam isteğini kim durdurur?', 'Athena ve Zeus', ['Telemakhos', 'Penelope', 'Poseidon'], 'Zeus yıldırım atar, Athena aileleri barışa zorlar; Odysseus İthaka\'da düzenini yeniden kurar.'),
  ('Aeneis\'te Aeneas\'ın zırhını ve kalkanını yapan tanrı kimdir?', 'Vulcanus', ['Mars', 'Neptunus', 'Mercurius'], 'Venüs\'ün isteğiyle yapılan kalkanın üzerinde Roma\'nın gelecekteki tarihi, Aktium savaşına kadar işlenmiştir.'),
  ('\'Mulan Baladı\' hangi öyküyü anlatır?', 'Babasının yerine erkek kılığında orduya katılan kızı', ['Bir keşişin Hindistan yolculuğunu', 'Bir haydut çetesinin isyanını', 'Bir imparatorun aşkını'], 'Kuzey dönemi halk şiiri olan balad, sonraki yüzyıllarda pek çok uyarlamaya kaynaklık etmiştir.'),
  ('Aşağıdakilerden hangisi geleneksel \'Dört Büyük Klasik Roman\' içinde yer almaz?', 'Jin Ping Mei', ['Üç Krallık Romanı', 'Su Kıyısı', 'Kızıl Odanın Rüyası'], 'Dört büyük klasik; Üç Krallık, Su Kıyısı, Batıya Yolculuk ve Kızıl Odanın Rüyası\'dır; Jin Ping Mei ise ayrı bir önemli romandır.'),
  ('Kelile ve Dimne\'nin çerçeve hikâyesinde Kelile ile Dimne kimlerdir?', 'İki çakal kardeş', ['İki kral oğlu ve vezir çocuğu', 'İki tüccar', 'İki kuş'], 'Dimne, hükümdar aslan ile boğa arasına fitne sokar; çakalların öyküsü eserin ana çerçevesidir.'),
  ('Aşağıdaki eserlerden hangisi Konfüçyüsçü geleneğin \'Dört Kitap\'ı arasında yer almaz?', 'Yijing', ['Büyük Öğrenim', 'Orta Yol', 'Mengzi'], 'Dört Kitap, Büyük Öğrenim, Orta Yol, Lunyu ve Mengzi\'den oluşur; Yijing Beş Klasik\'e aittir.'),
  ('\'Daodejing\' adındaki \'Dao\' ve \'De\' sözcükleri neyi anlatır?', 'Yol ve erdem', ['Gök ve yer', 'Yaşam ve ölüm', 'Doğu ve batı'], 'Daodejing \'Yol ve Erdem Kitabı\' olarak çevrilebilir; ilk bölüm Dao\'yu, ikinci bölüm De\'yi ele alır.'),
  ('Haiku\'da mevsimi çağrıştıran sözcüğe ne ad verilir?', 'Kigo', ['Kireji', 'Makurakotoba', 'Kakekotoba'], 'Kigo, haikunun mevsim ve doğa bağını kurar; kireji ise şiire bir kesme ya da vurgu sağlayan sözcüktür.'),
];
